import { z } from 'zod';

import { chatModeSchema, interestsSchema, langSchema, messageTextSchema } from '../schemas.ts';
import { NOTICE_CODES } from './events.ts';

// --- Shared building blocks ---------------------------------------------------------------

/** Session ids are UUIDs generated by the gateway. */
export const sessionIdSchema = z.uuid();

/** Random per-session id shown to other participants (never a visitor id). */
export const participantIdSchema = z.string().regex(/^[A-Za-z0-9_-]{8,32}$/);

export const MAX_SDP_BYTES = 16 * 1024;
export const MAX_ICE_CANDIDATE_LENGTH = 1024;

const emptyPayload = z.object({}).default({});

// --- Client → server payloads -------------------------------------------------------------

export const queueJoinSchema = z.object({
  mode: chatModeSchema,
  lang: langSchema,
  interests: interestsSchema.default([]),
  /**
   * If a session fails early through no fault of this visitor (the peer never acked or never
   * came back), requeue them automatically at the head of the queue (D-048).
   */
  autoRequeue: z.boolean().default(false),
  /** Opt in to joining group calls of 3–4 people (Part 12, landing-page toggle, off by default). */
  allowGroup: z.boolean().default(false),
});

export const queueLeaveSchema = emptyPayload;
export const pingSchema = emptyPayload;

export const sessionRefSchema = z.object({ sessionId: sessionIdSchema });

/**
 * Why a client skips. `rtc_failed`: WebRTC could not (re)connect after an ICE restart; the
 * session ends with `RTC_FAILED` and the others count as innocent (priority requeue, D-048).
 */
export const NEXT_REASONS = ['rtc_failed'] as const;
export const chatNextSchema = sessionRefSchema.extend({ reason: z.enum(NEXT_REASONS).optional() });
export const chatEndSchema = sessionRefSchema;
/** Must arrive within MATCH_ACK_TIMEOUT_MS of `match:found` (ghost-tab protection, D-047). */
export const matchAckSchema = sessionRefSchema;

/** After a socket reconnect, on any node (D-046). */
export const sessionResumeSchema = z.object({
  sessionId: sessionIdSchema,
  /** Last chat message id the client has; later messages are returned as `missedMessages`. */
  lastMessageId: z.string().min(1).max(64).optional(),
});

export const chatMessageSchema = z.object({
  sessionId: sessionIdSchema,
  text: messageTextSchema,
  /** Client-generated id echoed in acks so the sender can match optimistic messages. */
  clientMsgId: z.string().min(1).max(64),
});

export const chatTypingSchema = z.object({
  sessionId: sessionIdSchema,
  isTyping: z.boolean(),
});

/** `sdp` is the SDP text; the event name (offer/answer) carries the description type. */
export const rtcDescriptionSchema = z.object({
  sessionId: sessionIdSchema,
  to: participantIdSchema,
  sdp: z.string().min(1).max(MAX_SDP_BYTES),
});

/** Mirrors RTCIceCandidateInit; an empty `candidate` string signals end-of-candidates. */
export const iceCandidateSchema = z.object({
  candidate: z.string().max(MAX_ICE_CANDIDATE_LENGTH),
  sdpMid: z.string().max(64).nullable().optional(),
  sdpMLineIndex: z.number().int().min(0).max(255).nullable().optional(),
  usernameFragment: z.string().max(256).nullable().optional(),
});

export const rtcIceSchema = z.object({
  sessionId: sessionIdSchema,
  to: participantIdSchema,
  candidate: iceCandidateSchema,
});

export const CANDIDATE_TYPES = ['host', 'srflx', 'prflx', 'relay', 'unknown'] as const;
const candidateTypeSchema = z.enum(CANDIDATE_TYPES);
const metric = (max: number) => z.number().min(0).max(max).nullable();

export const rtcSummarySchema = z.object({
  sessionId: sessionIdSchema,
  peer: participantIdSchema,
  localCandidateType: candidateTypeSchema,
  remoteCandidateType: candidateTypeSchema,
  avgRttMs: metric(60_000),
  avgBitrateKbps: metric(100_000),
  timeToConnectedMs: metric(600_000),
  failed: z.boolean(),
});

/**
 * Server-assigned frame sampling for one participant (D-054): upload a downscaled frame of
 * the own outgoing video every `frameIntervalMs` (null = never), at most `maxFrames` frames
 * (absent/null = no limit).
 */
export const frameScheduleSchema = z.object({
  frameIntervalMs: z.number().int().positive().nullable(),
  maxFrames: z.number().int().positive().nullable().optional(),
});

export const moderationSignalSchema = z.object({
  sessionId: sessionIdSchema,
  about: z.union([participantIdSchema, z.literal('self')]),
  /** Classifier label, e.g. "nudity" (labels are defined in Part 8). */
  kind: z.string().regex(/^[a-z_]{1,32}$/),
  score: z.number().min(0).max(1),
});

// --- Server → client payloads -------------------------------------------------------------

export const queueWaitingSchema = z.object({ since: z.iso.datetime() });

export const peerRoleSchema = z.object({
  participantId: participantIdSchema,
  /** For this pair, the receiver creates the offer (impolite peer). */
  initiator: z.boolean(),
  /** Perfect-negotiation politeness for this pair, from the receiver's point of view. */
  polite: z.boolean(),
});

/** `mesh` = P2P (2 people); `sfu` = Janus VideoRoom (Part 11, D-050). */
export const TOPOLOGIES = ['mesh', 'sfu'] as const;

/**
 * Where and how to join the call's Janus room: the node's browser-facing WebSocket URL, the
 * room and this participant's own signed token (Janus API + the room's allowed list, D-051).
 * `epoch` increases with every topology change (upgrade, failover).
 */
export const sfuJoinSchema = z.object({
  wsUrl: z.url({ protocol: /^wss?$/ }),
  roomId: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
  token: z.string().min(1).max(512),
  epoch: z.number().int().positive(),
});

export const matchFoundSchema = z.object({
  sessionId: sessionIdSchema,
  mode: chatModeSchema,
  topology: z.enum(TOPOLOGIES),
  /** Present when the call starts on Janus (`topology: 'sfu'`). */
  sfu: sfuJoinSchema.optional(),
  maxParticipants: z.number().int().min(2).max(16),
  selfParticipantId: participantIdSchema,
  peers: z.array(peerRoleSchema),
  /** Server-chosen frame sampling for this participant (Part 8, D-054). */
  moderation: frameScheduleSchema,
  commonInterests: z.array(z.string()),
});

/** A new participant joined the group call (Part 12); they publish to the Janus room. */
export const participantJoinedSchema = z.object({
  sessionId: sessionIdSchema,
  participantId: participantIdSchema,
});

/** Id of one "add a person" round. */
export const addRequestIdSchema = z.string().regex(/^[A-Za-z0-9_-]{8,32}$/);

export const callRespondAddSchema = z.object({
  sessionId: sessionIdSchema,
  requestId: addRequestIdSchema,
  accept: z.boolean(),
});

/** `call:addRequested`: `by` asked; everyone present (incl. `by`) must accept before `expiresAt`. */
export const callAddRequestedSchema = z.object({
  sessionId: sessionIdSchema,
  requestId: addRequestIdSchema,
  by: participantIdSchema,
  expiresAt: z.iso.datetime(),
});

/** `call:seeking`: everyone agreed; the call looks for one more person until `until`. */
export const callSeekingSchema = z.object({
  sessionId: sessionIdSchema,
  until: z.iso.datetime(),
});

export const SEEK_CANCEL_REASONS = [
  /** Someone declined (or the requester withdrew). */
  'declined',
  /** Not everyone answered within ADD_REQUEST_TTL_MS. */
  'expired',
  /** Nobody joined within SEEK_PARTICIPANT_TIMEOUT_MS. */
  'timeout',
  /** Someone left during the round: a new person needs a fresh round. */
  'left',
  /** No media server for the group call. */
  'unavailable',
] as const;

export const callSeekCancelledSchema = z.object({
  sessionId: sessionIdSchema,
  reason: z.enum(SEEK_CANCEL_REASONS),
});

/** `call:topologyReady` / `call:sfuToken`: about the topology of this epoch. */
export const callEpochSchema = z.object({
  sessionId: sessionIdSchema,
  epoch: z.number().int().positive(),
});

/** Why a mesh → SFU switch was rolled back (the P2P call keeps running). */
export const ROLLBACK_REASONS = ['timeout', 'failed', 'unavailable'] as const;

/**
 * `call:topology`: join Janus (an upgrade, or a new room after a node failed — same shape,
 * higher epoch), or stay on P2P because the upgrade failed. Never sfu → mesh otherwise.
 */
export const callTopologySchema = z.discriminatedUnion('topology', [
  z.object({
    sessionId: sessionIdSchema,
    topology: z.literal('sfu'),
    epoch: z.number().int().positive(),
    sfu: sfuJoinSchema.omit({ epoch: true }),
  }),
  z.object({
    sessionId: sessionIdSchema,
    topology: z.literal('mesh'),
    epoch: z.number().int().positive(),
    reason: z.enum(ROLLBACK_REASONS),
  }),
]);

export const sfuTokenSchema = z.object({ token: z.string().min(1).max(512) });

export const chatMessageOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  id: z.string().min(1),
  text: z.string(),
  at: z.iso.datetime(),
});

export const chatTypingOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  isTyping: z.boolean(),
});

export const rtcDescriptionOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  sdp: z.string(),
});

export const rtcIceOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  candidate: iceCandidateSchema,
});

/** `peer:reconnecting` / `peer:resumed`: the peer's signaling connection dropped / came back. */
export const peerPresenceSchema = z.object({
  sessionId: sessionIdSchema,
  participantId: participantIdSchema,
});

export const peerLeftSchema = z.object({
  sessionId: sessionIdSchema,
  participantId: participantIdSchema,
  reason: z.enum(['left', 'disconnected']),
  sessionEnded: z.boolean(),
});

export const systemNoticeSchema = z.object({
  code: z.enum(NOTICE_CODES),
  message: z.string(),
  /** FRAME_SCHEDULE: the session and its new schedule. */
  sessionId: sessionIdSchema.optional(),
  moderation: frameScheduleSchema.optional(),
});

export const pongSchema = z.object({ serverTime: z.number().int() });

export const chatMessageAckSchema = z.object({
  id: z.string().min(1),
  at: z.iso.datetime(),
  /** The text as relayed, when the filter masked profanity. */
  text: z.string().optional(),
});

export const sessionResumedSchema = z.object({
  selfParticipantId: participantIdSchema,
  peers: z.array(peerRoleSchema),
  /** Messages from others sent while this client was away (oldest first). */
  missedMessages: z.array(chatMessageOutSchema),
  /**
   * The call's Janus room as of now (Part 11): a `call:topology` sent while this client was
   * away (an upgrade, a failover) would otherwise be lost. Absent while the call is P2P only.
   */
  sfu: sfuJoinSchema.optional(),
});
